INSERT INTO `services` (`title`, `slug`, `icon`, `summary`, `description`, `seo_title`, `seo_description`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES
('برندسازی', 'branding', 'branding', 'طراحی هویت یکتا و حرفه‌ای برای برند شما.', 'توضیحات کامل خدمت برندسازی. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'خدمات برندسازی | مسلم ابراهیمی', 'ساخت هویت بصری منسجم و حرفه‌ای برای برند شما.', 1, 1, NOW(), NOW()),
('طراحی لوگو', 'logo-design', 'logo', 'طراحی لوگوی اختصاصی، مینیمال و به‌یادماندنی.', 'توضیحات کامل خدمت طراحی لوگو. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'طراحی لوگو | مسلم ابراهیمی', 'طراحی لوگوی حرفه‌ای و منحصربه‌فرد برای برند شما.', 2, 1, NOW(), NOW()),
('طراحی پوستر', 'poster-design', 'poster', 'پوسترهای تبلیغاتی جذاب برای محصول و رویداد.', 'توضیحات کامل خدمت طراحی پوستر. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'طراحی پوستر | مسلم ابراهیمی', 'پوسترهای خلاقانه و تأثیرگذار برای کمپین‌های شما.', 3, 1, NOW(), NOW()),
('طراحی بنر', 'banner-design', 'banner', 'بنرهای تبلیغاتی متنوع برای فضای مجازی و چاپ.', 'توضیحات کامل خدمت طراحی بنر. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'طراحی بنر | مسلم ابراهیمی', 'بنرهای تبلیغاتی چشم‌نواز برای شبکه‌های اجتماعی و وب‌سایت.', 4, 1, NOW(), NOW()),
('طراحی بروشور', 'brochure-design', 'brochure', 'بروشورهای حرفه‌ای برای معرفی محصولات و خدمات.', 'توضیحات کامل خدمت طراحی بروشور. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'طراحی بروشور | مسلم ابراهیمی', 'طراحی بروشورهای سازمانی و تبلیغاتی با چیدمان جذاب.', 5, 1, NOW(), NOW()),
('طراحی کارت ویزیت', 'business-card-design', 'card', 'کارت ویزیت‌های شیک و متمایز.', 'توضیحات کامل خدمت طراحی کارت ویزیت. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'طراحی کارت ویزیت | مسلم ابراهیمی', 'کارت ویزیت‌های حرفه‌ای برای شبکه‌سازی موفق.', 6, 1, NOW(), NOW()),
('موشن‌گرافیک', 'motion-graphics', 'motion', 'انیمیشن‌های خلاقانه برای معرفی برند و محصول.', 'توضیحات کامل خدمت موشن‌گرافیک. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'موشن‌گرافیک | مسلم ابراهیمی', 'موشن‌گرافیک‌های حرفه‌ای برای جذب بیشتر مخاطب.', 7, 1, NOW(), NOW()),
('تولید ویدیو', 'video-production', 'video', 'تولید و تدوین ویدیوهای تبلیغاتی و معرفی.', 'توضیحات کامل خدمت تولید ویدیو. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'تولید ویدیو | مسلم ابراهیمی', 'ویدیوهای تبلیغاتی و معرفی با کیفیت حرفه‌ای.', 8, 1, NOW(), NOW()),
('بازاریابی دیجیتال', 'digital-marketing', 'marketing', 'کمپین‌های هدفمند برای رشد کسب‌وکار آنلاین.', 'توضیحات کامل خدمت بازاریابی دیجیتال. این متن نمونه است و باید توسط مدیر در پنل تکمیل شود.', 'بازاریابی دیجیتال | مسلم ابراهیمی', 'کمپین‌های بازاریابی دیجیتال با نتایج قابل اندازه‌گیری.', 9, 1, NOW(), NOW()),
