INSERT INTO `home_sections` (`section_key`, `title`, `subtitle`, `body`, `cta_text`, `cta_url`, `is_published`, `sort_order`, `updated_at`) VALUES
('hero', 'تجربه‌های دیجیتال که کسب‌وکار شما را رشد می‌دهند', 'شرکت خدماتی و بازاریابی مسلم ابراهیمی', 'ما به برندها کمک می‌کنیم تا با طراحی‌های زیبا و راهکارهای بازاریابی هدفمند، آنلاین دیده شوند و رشد کنند. این متن نمونه است و از پنل قابل ویرایش است.', 'شروع کنید', '#contact', 1, 1, NOW()),
('about', 'درباره ما', 'چه کسانی هستیم', 'شرکت خدماتی و بازاریابی مسلم ابراهیمی ارائه‌دهنده خدمات جامع برندسازی، طراحی، تولید محتوا و بازاریابی دیجیتال است. این متن نمونه است و باید توسط مدیر تکمیل شود.', NULL, NULL, 1, 2, NOW()),
('cta', 'آماده رشد کسب‌وکار خود هستید؟', 'با ما در تماس باشید', 'با تیم ما تماس بگیرید تا برای برند شما بهترین راهکار را ارائه دهیم.', 'دریافت مشاوره', '#contact', 1, 3, NOW())
