INSERT INTO `faqs` (`question`, `answer`, `is_published`, `sort_order`, `created_at`, `updated_at`) VALUES
('برای شروع همکاری چه باید کرد؟', 'کافی است از طریق فرم تماس یا شماره‌های درج‌شده با ما در ارتباط باشید. تیم ما در اسرع وقت برای مشاوره با شما تماس می‌گیرد. (پاسخ نمونه — قابل ویرایش در پنل)', 1, 1, NOW(), NOW()),
('زمان اجرای پروژه‌ها چقدر است؟', 'بسته به نوع و اندازه پروژه متفاوت است. پس از بررسی نیاز شما، زمان‌بندی دقیق اعلام می‌شود. (پاسخ نمونه — قابل ویرایش در پنل)', 1, 2, NOW(), NOW()),
('آیا امکان ویرایش طرح پس از تحویل وجود دارد؟', 'بله، در بسته‌های طراحی امکان اعمال اصلاحات منصفانه پیش‌بینی شده است. جزئیات هنگام همکاری توضیح داده می‌شود. (پاسخ نمونه — قابل ویرایش در پنل)', 1, 3, NOW(), NOW())
