-- ==================================================================
-- داده اولیه نمونه برای وب‌سایت مسلم ابراهیمی
-- توجه: هیچ حساب مدیر با گذرواژه ثابت در این فایل نیست.
-- حساب مدیر را با اسکریپت create_admin.php ایجاد کنید (به README مراجعه کنید).
-- محتوای شماره تماس از پوستر رسمی شرکت گرفته شده و کاملاً قابل ویرایش است.
-- سایر داده‌ها «نمونه» هستند و باید توسط مدیر تکمیل/جایگزین شوند.
-- ==================================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------------
-- تنظیمات عمومی (کلید-مقدار)
-- ------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`);

-- ------------------------------------------------------------------
-- خدمات اولیه شرکت (۱۲ خدمت از پوستر رسمی)
-- ------------------------------------------------------------------

-- ------------------------------------------------------------------
-- دسته‌بندی نمونه‌کارها (نمونه — قابل ویرایش/حذف از پنل)
-- ------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);

-- ------------------------------------------------------------------
-- محتوای بخش‌های صفحه خانه (کلید یکتا)
-- ------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `subtitle` = VALUES(`subtitle`), `body` = VALUES(`body`);

-- ------------------------------------------------------------------
-- مزایا / مراحل همکاری (نمونه)
-- ------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`);

-- ------------------------------------------------------------------
-- پرسش‌های پرتکرار (نمونه)
-- ------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `question` = VALUES(`question`);

